    mc = min(c for r, c, v in markers)
    ar = min(r for r, c in eight)
    ac = min(c for r, c in eight)

    for r, c, color in markers:
        r0 = ar + (r - mr) * scale
        c0 = ac + (c - mc) * scale
        for rr in range(r0, r0 + scale):
            for cc in range(c0, c0 + scale):
